async ({ workspace: { read, search } }) => {
  const [pkg, t1, t2] = await Promise.all([
    read("package.json", { format: "raw" }),
    search("git\\.tag|gitFunctions|\"tag\"", { path: "test", regex: true, limit: 40, contextLines: 0 }),
    search("prepareNpmCommand|npm\\.run\\(", { path: "test", regex: true, limit: 40, contextLines: 0 }),
  ]);
  const sl = (r: any) => r.matches?.map((m: any) => `${m.file}:${m.line}: ${m.text?.slice(0, 160)}`) ?? r;
  return { scripts: JSON.parse(pkg.content).scripts, t1: sl(t1), t2: sl(t2) };
}
